{"command":"cat << 'EOF' > src/fsm/context.tsx
import React, { createContext, useContext, useState, ReactNode } from 'react';
import { FsmState, createInitialState, PageId } from './engine';

interface FsmContextType {
  state: FsmState;
  navigate: (to: PageId) => void;
  updateData: (payload: Partial<FsmState['data']>) => void;
  clearData: (keys: Array<keyof FsmState['data']>) => void;
}

const FsmContext = createContext<FsmContextType | undefined>(undefined);

export const FsmProvider = ({ children }: { children: ReactNode }) => {
  const [state, setState] = useState<FsmState>(createInitialState());

  const navigate = (to: PageId) => {
    setState((prev) => ({ ...prev, currentPage: to }));
  };

  const updateData = (payload: Partial<FsmState['data']>) => {
    setState((prev) => ({ ...prev, data: { ...prev.data, ...payload } }));
  };

  const clearData = (keys: Array<keyof FsmState['data']>) => {
    setState((prev) => {
      const nextData = { ...prev.data };
      keys.forEach(k => {
        nextData[k] = null;
      });
      return { ...prev, data: nextData };
    });
  };

  return (
    <FsmContext.Provider value={{ state, navigate, updateData, clearData }}>
      {children}
    </FsmContext.Provider>
  );
};

export const useFsm = () => {
  const context = useContext(FsmContext);
  if (!context) throw new Error('useFsm must be used within FsmProvider');
  return context;
};
EOF
"}

