import React from 'react';
import { useFsm } from './fsm/context';
import HomePage from './pages/HomePage';
import WorkspaceListPage from './pages/WorkspaceListPage';
import ChannelListPage from './pages/ChannelListPage';
import ChannelViewPage from './pages/ChannelViewPage';
import MessageThreadPage from './pages/MessageThreadPage';
import SendMessageSuccessPage from './pages/SendMessageSuccessPage';
import ScheduleMessageFormPage from './pages/ScheduleMessageFormPage';
import ScheduleMessageSuccessPage from './pages/ScheduleMessageSuccessPage';
import CreateChannelPage from './pages/CreateChannelPage';
import CreateChannelSuccessPage from './pages/CreateChannelSuccessPage';
import DmListPage from './pages/DmListPage';
import DmViewPage from './pages/DmViewPage';
import CreateDmPage from './pages/CreateDmPage';
import CreateDmSuccessPage from './pages/CreateDmSuccessPage';
import ProfileSettingsPage from './pages/ProfileSettingsPage';
import UpdateProfileSuccessPage from './pages/UpdateProfileSuccessPage';

function App() {
  const { state } = useFsm();

  const renderPage = () => {
    switch (state.currentPage) {
      case 'HOME': return <HomePage />;
      case 'WORKSPACE_LIST': return <WorkspaceListPage />;
      case 'CHANNEL_LIST': return <ChannelListPage />;
      case 'CHANNEL_VIEW': return <ChannelViewPage />;
      case 'MESSAGE_THREAD': return <MessageThreadPage />;
      case 'SEND_MESSAGE_SUCCESS': return <SendMessageSuccessPage />;
      case 'SCHEDULE_MESSAGE_FORM': return <ScheduleMessageFormPage />;
      case 'SCHEDULE_MESSAGE_SUCCESS': return <ScheduleMessageSuccessPage />;
      case 'CREATE_CHANNEL': return <CreateChannelPage />;
      case 'CREATE_CHANNEL_SUCCESS': return <CreateChannelSuccessPage />;
      case 'DM_LIST': return <DmListPage />;
      case 'DM_VIEW': return <DmViewPage />;
      case 'CREATE_DM': return <CreateDmPage />;
      case 'CREATE_DM_SUCCESS': return <CreateDmSuccessPage />;
      case 'PROFILE_SETTINGS': return <ProfileSettingsPage />;
      case 'UPDATE_PROFILE_SUCCESS': return <UpdateProfileSuccessPage />;
      default: return <div>404 Page Not Found</div>;
    }
  };

  return (
    <div className="min-h-screen bg-background text-textPrimary font-sans selection:bg-accent selection:text-white">
      {renderPage()}
    </div>
  );
}

export default App;
EOF
