          >
            <Button 
              variant="outline" 
              disabled={!state.data.cookie_consent_given}
            >
              Workspaces ▼
            </Button>

            {showHoverMenu && state.data.cookie_consent_given && (
              <div className="absolute top-full right-0 mt-2 w-48 bg-surface border border-subtle shadow-xl rounded-md overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-200">
                <button 
                  id="top-nav-workspaces .menu-all-workspaces"
                  className="w-full text-left px-4 py-3 hover:bg-subtle transition-colors text-sm font-medium border-b border-subtle/50 menu-all-workspaces"
                  onClick={handleGoWorkspaceListHoverAll}
