              <Button 
                id="cookie-accept" 
                onClick={handleCookieAccept}
                className="flex-1 md:flex-none bg-slackGreen hover:bg-emerald-600 text-white"
              >
                Accept All
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
