{"command":"cat << 'EOF' > src/pages/ChannelViewPage.tsx
import React, { useState } from 'react';
import { useFsm } from '../fsm/context';
import { Layout, Sidebar, MainContent } from '../components/Layout';
import { Button } from '../components/Button';

export default function ChannelViewPage() {
  const { state, updateData, navigate, clearData } = useFsm();

  const [searchText, setSearchText] = useState('');

  const channel = state.data.channels?.find((c: any) => c.id === state.data.selected_channel_id);
  const allMessages = state.data.messages?.filter((m: any) => m.channel_id === state.data.selected_channel_id) || [];

  const isSearched = state.data.channel_view_has_searched === true;
  const filteredMessages = isSearched 
    ? allMessages.filter((m: any) => m.id === state.data.matched_message_id)
    : allMessages;

  const handleSearchMessages = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && searchText) {
      const match = allMessages.find((m: any) => m.text.toLowerCase().includes(searchText.toLowerCase()));
      if (match) {
        updateData({ 
          matched_message_id: match.id,
          channel_view_has_searched: true
        });
      }
    }
  };

  const handleOpenMessage = (messageId: string, type: 'matched' | 'visible') => {
    if (type === 'matched') {
      clearData(['channel_view_has_searched']);
    } else {
      clearData(['channel_view_viewport_anchor_id']);
    }

    updateData({ selected_message_id: messageId });
    navigate('MESSAGE_THREAD');
  };

  const handleScrollIntoView = (messageId: string) => {
    updateData({ channel_view_viewport_anchor_id: messageId });
  };

  const handleTypeMessage = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    updateData({ compose_message_text: e.target.value });
  };

  const handleToggleImportant = () => {
    updateData({ compose_is_important: true });
  };

  const handleAttachFile = () => {
    updateData({ compose_has_attachment: true });
  };

  const handleScheduleForm = () => {
    if (state.data.compose_message_text?.length > 0) {
      navigate('SCHEDULE_MESSAGE_FORM');
    }
  };

  const handleSendMessage = () => {
    if (state.data.compose_message_text?.length > 0) {
      clearData(['compose_message_text', 'compose_has_attachment', 'compose_is_important']);
      navigate('SEND_MESSAGE_SUCCESS');
    }
  };

  const handleBackChannelList = () => {
    navigate('CHANNEL_LIST');
  };

  return (
    <Layout>
      <MainContent className="flex flex-col h-full bg-background relative">
        {/* Header */}
        <header className="h-16 border-b border-subtle flex items-center justify-between px-6 bg-surface z-10">
          <div className="flex items-center gap-4">
            <Button 
              id="back-channel-list" 
              variant="ghost" 
              size="sm" 
              onClick={handleBackChannelList}
              className="text-textSecondary hover:text-textPrimary w-8 h-8 p-0"
            >
              ←
            </Button>
            <div className="font-bold text-lg flex items-center gap-2">
              <span className="text-textSecondary text-xl font-normal">#</span>
              {channel?.name || 'Channel'}
            </div>
          </div>
          <div className="relative w-64">
            <input 
              id="channel-search-messages-input"
              type="text"
              placeholder="Search messages..."
              className="w-full bg-background border border-subtle rounded-md text-sm px-3 py-1.5 focus:outline-none focus:border-accent text-textPrimary"
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              onKeyDown={handleSearchMessages}
            />
          </div>
        </header>

        {/* Message List */}
        <div 
          id="message-list-container"
          className="flex-1 overflow-y-auto p-6 space-y-6 flex flex-col justify-end"
          onWheel={(e) => {
            if(e.deltaY < 0 && filteredMessages.length > 0) {
              // Scrolling up to older messages simulates scroll anchor
              handleScrollIntoView(filteredMessages[0].id);
            }
          }}
        >
          <div id="message-list" className="space-y-6 max-w-4xl w-full mx-auto">
            {filteredMessages.map((msg: any) => {
              let rowClass = 'message-row-visible';
              if (isSearched) rowClass = 'message-row-matched';

              const canOpenAny = !isSearched && state.data.channel_view_viewport_anchor_id;

              return (
                <div 
                  key={msg.id}
                  className={`group flex gap-4 hover:bg-subtle/30 p-2 -mx-2 rounded-lg transition-colors cursor-pointer ${rowClass}`}
                  onClick={() => {
                    if (isSearched) handleOpenMessage(msg.id, 'matched');
                    else if (canOpenAny) handleOpenMessage(msg.id, 'visible');
                  }}
                >
                  <div className="w-10 h-10 rounded bg-subtle flex-shrink-0 flex items-center justify-center font-bold text-lg text-textSecondary group-hover:text-textPrimary transition-colors">
                    {msg.sender.charAt(0)}
                  </div>
                  <div className="flex-1 min-w-0">
