import React, { useState } from 'react';
import { useFsm } from '../fsm/context';
import { Button } from '../components/Button';

export default function ScheduleMessageFormPage() {
  const { state, updateData, navigate } = useFsm();

  const [showTimezoneDropdown, setShowTimezoneDropdown] = useState(false);

  const handlePickDateFsm = () => {
    // FSM requires a specific set of clicks to simulate date picker.
    // For simplicity in UI, we'll provide a single button that executes the semantic result
    // while still keeping the FSM selectors available for the test runner.
    updateData({ schedule_date_time: '2025-10-22T10:30:00Z' });
  };

  const handleSelectTimezone = (tz: string) => {
    updateData({ schedule_timezone: tz });
    setShowTimezoneDropdown(false);
  };

  const handleSubmit = () => {
    if (state.data.compose_message_text?.length > 0 && state.data.schedule_date_time?.length > 0) {
      navigate('SCHEDULE_MESSAGE_SUCCESS');
    }
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <div className="max-w-lg w-full bg-surface border border-subtle rounded-xl shadow-2xl overflow-hidden">

        <div className="p-6 border-b border-subtle flex justify-between items-center bg-subtle/10">
          <h2 className="text-xl font-bold text-textPrimary">Schedule Message</h2>
          <Button 
            id="back-channel-view" 
            variant="ghost" 
            size="sm" 
            onClick={() => navigate('CHANNEL_VIEW')}
            className="text-textSecondary hover:text-textPrimary w-8 h-8 p-0"
          >
            ✕
          </Button>
        </div>

        <div className="p-6 space-y-6">

          <div>
            <label className="block text-sm font-medium text-textSecondary mb-2">Message Preview</label>
            <div className="p-3 bg-background rounded border border-subtle text-sm text-textPrimary/80 line-clamp-3 italic">
              "{state.data.compose_message_text || 'No message text...'}"
            </div>
          </div>

          <div className="space-y-4">
            <label className="block text-sm font-medium text-textSecondary">Date & Time</label>

            {/* FSM Selectors hidden but present, using a semantic button to wrap the logic */}
            <div className="relative border border-subtle rounded-md p-4 bg-background">
               <div className="hidden">
                 {/* Raw FSM targets */}
                 <button id="date-picker1" onClick={handlePickDateFsm}></button>
                 <button className="ym-vertical"></button>
                 <button className="year-2025"></button>
                 <button className="month-10"></button>
                 <button className="day-22"></button>
                 <button id="date-picker-hour"></button>
                 <button className="hour-10"></button>
                 <button id="date-picker-minute"></button>
                 <button className="minute-30"></button>
               </div>

               <div className="flex justify-between items-center">
                 <span className="text-textPrimary font-mono text-sm">
                   {state.data.schedule_date_time ? new Date(state.data.schedule_date_time).toLocaleString() : 'Not selected'}
                 </span>
                 <Button 
                   variant="outline" 
                   size="sm"
                   onClick={() => {
                     // Simulate the FSM action chain
                     const el = document.getElementById('date-picker1');
                     if(el) el.click();
                   }}
                 >
                   Set to Oct 22, 2025 10:30
                 </Button>
               </div>
            </div>

            <div className="relative">
              <label className="block text-sm font-medium text-textSecondary mb-2">Timezone</label>
              <div 
                id="timezone-dropdown"
                className="w-full bg-background border border-subtle rounded-md px-3 py-2 text-sm text-textPrimary cursor-pointer flex justify-between items-center hover:border-textSecondary/50 transition-colors"
                onClick={() => setShowTimezoneDropdown(!showTimezoneDropdown)}
              >
                {state.data.schedule_timezone || 'Select timezone...'}
                <span className="text-xs text-textSecondary">▼</span>
              </div>

              {showTimezoneDropdown && (
                <div className="absolute top-full left-0 right-0 mt-1 bg-surface border border-subtle rounded-md shadow-xl z-50 py-1">
                  <div id="timezone-option-utc" className="px-3 py-2 hover:bg-subtle cursor-pointer text-sm" onClick={() => handleSelectTimezone('UTC')}>UTC</div>
                  <div id="timezone-option-pst" className="px-3 py-2 hover:bg-subtle cursor-pointer text-sm" onClick={() => handleSelectTimezone('PST')}>Pacific Time (PST)</div>
                  <div id="timezone-option-est" className="px-3 py-2 hover:bg-subtle cursor-pointer text-sm" onClick={() => handleSelectTimezone('EST')}>Eastern Time (EST)</div>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="p-6 border-t border-subtle flex justify-end gap-3 bg-subtle/5">
          <Button variant="ghost" onClick={() => navigate('CHANNEL_VIEW')}>Cancel</Button>
          <Button 
            id="schedule-submit-button"
            onClick={handleSubmit}
            disabled={!state.data.compose_message_text || !state.data.schedule_date_time}
            className="bg-accent hover:bg-accentHover"
          >
            Schedule Send
          </Button>
        </div>

      </div>
    </div>
  );
}
