export default function CreateChannelPage() {
  const { state, updateData, navigate } = useFsm();

  const [showPrivacyDropdown, setShowPrivacyDropdown] = useState(false);
  const [inviteText, setInviteText] = useState('');

  const handleTypeName = (e: React.ChangeEvent<HTMLInputElement>) => {
    updateData({ new_channel_name: e.target.value });
  };

  const handleTypeDescription = (e: React.ChangeEvent<HTMLInputElement>) => {
    updateData({ new_channel_description: e.target.value });
  };

  const handleSelectPrivacy = (privacy: string) => {
    updateData({ new_channel_privacy: privacy });
    setShowPrivacyDropdown(false);
  };

  const handleAddInvite = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && inviteText) {
      const current = state.data.new_channel_invite_ids || [];
      if (!current.includes(inviteText)) {
        updateData({ new_channel_invite_ids: [...current, inviteText] });
      }
      setInviteText('');
    }
  };

  const handleSubmit = () => {
    if (state.data.new_channel_name?.length > 0) {
      navigate('CREATE_CHANNEL_SUCCESS');
