          id="back-channel-list" 
          variant="ghost" 
          onClick={() => navigate('CHANNEL_LIST')}
          className="mb-6 text-textSecondary hover:text-textPrimary"
        >
          ← Back
        </Button>

        <h1 className="text-4xl font-extrabold text-textPrimary mb-2">Create a channel</h1>
        <p className="text-textSecondary mb-8 text-lg">Channels are where your team communicates. They're best when organized around a topic — #marketing, for example.</p>

        <div className="space-y-8 bg-surface border border-subtle p-8 rounded-xl shadow-sm">

          <div className="space-y-2">
            <label className="block text-sm font-bold text-textPrimary">Name</label>
            <input 
              id="channel-name-input"
              type="text"
              placeholder="e.g. plan-budget"
              className="w-full bg-background border border-subtle rounded-md px-4 py-3 focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent text-textPrimary transition-all"
              value={state.data.new_channel_name || ''}
              onChange={handleTypeName}
            />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-bold text-textPrimary">
              Description <span className="text-textSecondary font-normal">(optional)</span>
            </label>
            <input 
              id="channel-description-input"
              type="text"
              className="w-full bg-background border border-subtle rounded-md px-4 py-3 focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent text-textPrimary transition-all"
              value={state.data.new_channel_description || ''}
              onChange={handleTypeDescription}
            />
            <p className="text-xs text-textSecondary mt-1">What's this channel about?</p>
          </div>

          <div className="space-y-2 relative">
            <label className="block text-sm font-bold text-textPrimary">Privacy</label>
            <div 
              id="channel-privacy-dropdown"
              className="w-full bg-background border border-subtle rounded-md px-4 py-3 cursor-pointer flex justify-between items-center hover:border-textSecondary/50 transition-colors"
              onClick={() => setShowPrivacyDropdown(!showPrivacyDropdown)}
            >
              <span className="text-textPrimary capitalize">{state.data.new_channel_privacy || 'Select...'}</span>
              <span className="text-xs text-textSecondary">▼</span>
            </div>
            {showPrivacyDropdown && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-surface border border-subtle rounded-md shadow-xl z-50 overflow-hidden">
                <div id="privacy-option-public" className="px-4 py-3 hover:bg-subtle cursor-pointer" onClick={() => handleSelectPrivacy('public')}>
                  <div className="font-bold">Public</div>
                  <div className="text-xs text-textSecondary mt-0.5">Anyone in your workspace can join</div>
                </div>
                <div id="privacy-option-private" className="px-4 py-3 hover:bg-subtle cursor-pointer border-t border-subtle/50" onClick={() => handleSelectPrivacy('private')}>
                  <div className="font-bold flex items-center gap-1">🔒 Private</div>
                  <div className="text-xs text-textSecondary mt-0.5">Only invited members can view or join</div>
