            </label>

            <div className="flex flex-wrap gap-2 mb-2">
              {state.data.new_channel_invite_ids?.map((id: string) => (
                <span key={id} className="inline-flex items-center px-2.5 py-1 rounded bg-accent/20 text-accent text-sm font-medium">
                  {id}
                </span>
              ))}
            </div>

            <input 
              id="channel-invite-input"
              type="text"
              placeholder="Search by name or email, hit Enter to add"
