import { useFsm } from '../fsm/context';
import { Layout, Sidebar, MainContent } from '../components/Layout';
import { Button } from '../components/Button';

export default function DmListPage() {
  const { state, updateData, navigate, clearData } = useFsm();

  const [filterText, setFilterText] = useState('');
  const [searchText, setSearchText] = useState('');

  const dms = state.data.direct_messages || [];

  const isFiltered = state.data.dm_list_filters_applied === true;
  const isSearched = state.data.dm_list_has_searched === true;

  const filteredDms = dms.filter((dm: any) => {
    if (isFiltered && !dm.is_recent) return false;
    if (isSearched && dm.id !== state.data.matched_dm_id) return false;
    return true;
  });

  const handleApplyFilter = () => {
    updateData({ dm_list_filters_applied: true });
  };

  const handleSearch = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && searchText) {
      const match = dms.find((dm: any) => dm.recipient.toLowerCase().includes(searchText.toLowerCase()));
      if (match) {
        updateData({ 
          matched_dm_id: match.id,
          dm_list_has_searched: true
        });
