export default function ProfileSettingsPage() {
  const { state, updateData, navigate } = useFsm();

  const [showTimezoneDropdown, setShowTimezoneDropdown] = useState(false);

  // Fallback to mock data if FSM state is null
  const currentUser = state.data.current_user || {};
  const displayName = state.data.profile_display_name ?? currentUser.display_name;
