  const handleTypeDisplayName = (e: React.ChangeEvent<HTMLInputElement>) => {
    updateData({ profile_display_name: e.target.value });
  };

  const handleTypeTitle = (e: React.ChangeEvent<HTMLInputElement>) => {
    updateData({ profile_title: e.target.value });
  };

  const handleSelectTimezone = (tz: string) => {
    updateData({ profile_timezone: tz });
    setShowTimezoneDropdown(false);
  };

  const handleSave = () => {
    if (displayName?.length > 0) {
      navigate('UPDATE_PROFILE_SUCCESS');
    }
  };

  return (
    <div className="min-h-screen bg-background flex flex-col pt-12 items-center px-4">
      <div className="w-full max-w-2xl">
