            </div>
            <Button variant="outline" className="w-full text-sm">Upload Photo</Button>
          </div>

          {/* Form Side */}
          <div className="flex-1 space-y-6 bg-surface border border-subtle p-6 rounded-xl shadow-sm">

            <div className="space-y-2">
              <label className="block text-sm font-bold text-textPrimary">Display Name</label>
              <input 
                id="profile-display-name-input"
                type="text"
                className="w-full bg-background border border-subtle rounded-md px-4 py-2.5 focus:outline-none focus:border-accent text-textPrimary"
                value={displayName || ''}
                onChange={handleTypeDisplayName}
              />
              <p className="text-xs text-textSecondary">This could be your first name, or a nickname — however you’d like people to refer to you in Slack.</p>
            </div>

            <div className="space-y-2">
              <label className="block text-sm font-bold text-textPrimary">What I do</label>
              <input 
                id="profile-title-input"
                type="text"
                className="w-full bg-background border border-subtle rounded-md px-4 py-2.5 focus:outline-none focus:border-accent text-textPrimary"
                value={title || ''}
                onChange={handleTypeTitle}
              />
              <p className="text-xs text-textSecondary">Let people know what your role is.</p>
            </div>

            <div className="space-y-2 relative">
              <label className="block text-sm font-bold text-textPrimary">Time zone</label>
              <div 
                id="profile-timezone-dropdown"
                className="w-full bg-background border border-subtle rounded-md px-4 py-2.5 cursor-pointer flex justify-between items-center hover:border-textSecondary/50 transition-colors text-textPrimary"
                onClick={() => setShowTimezoneDropdown(!showTimezoneDropdown)}
